757	  public static Triple<RecordMergeMode, String, String> inferCorrectMergingBehavior(RecordMergeMode recordMergeMode, String payloadClassName,
758	                                                                                    String recordMergeStrategyId) {
759	    RecordMergeMode inferredRecordMergeMode;
760	    String inferredPayloadClassName;
761	    String inferredRecordMergeStrategyId;
762	
763	    if (isNullOrEmpty(payloadClassName)) {
764	      if (isNullOrEmpty(recordMergeStrategyId)) {
765	        // no payload class name or merge strategy ID. If nothing is set then we default. User cannot set custom because no payload or strategy is set
766	        checkArgument(recordMergeMode != RecordMergeMode.CUSTOM,
767	            "Custom merge mode should only be used if you set a payload class or merge strategy ID");
768	        if (recordMergeMode == null) {
769	          inferredRecordMergeMode = RECORD_MERGE_MODE.defaultValue();
770	        } else {
771	          inferredRecordMergeMode = recordMergeMode;
772	        }
773	
774	        // set merger strategy based on merge mode
775	        if (inferredRecordMergeMode == COMMIT_TIME_ORDERING) {
776	          inferredRecordMergeStrategyId = COMMIT_TIME_BASED_MERGE_STRATEGY_UUID;
777	        } else if (inferredRecordMergeMode == EVENT_TIME_ORDERING) {
778	          inferredRecordMergeStrategyId = DEFAULT_MERGE_STRATEGY_UUID;
779	        } else {
780	          throw new IllegalStateException("Merge Mode: '" + inferredRecordMergeMode + "' has not been fully implemented.");
781	        }
782	      } else {
783	        // no payload class but merge strategy ID is set. Need to validate that strategy and merge mode align if both are set
784	        inferredRecordMergeStrategyId = recordMergeStrategyId;
785	        if (recordMergeStrategyId.equals(DEFAULT_MERGE_STRATEGY_UUID)) {
786	          checkArgument(recordMergeMode == null || recordMergeMode == EVENT_TIME_ORDERING,
787	              "Default merge strategy ID can only be used with the merge mode of EVENT_TIME_ORDERING");
